long vi() {
    if (p >= data.length) {
        throw err();
    }
    int b = data[p++] & 255;
    int width = 1 << (b >>> 6);
    if (width > data.length - p) {
        throw err();
    }
    long v = b & 0x3fL;
    for (int i = 1; i < width; i++) {
        v = (v << 8) | (data[p++] & 255L);
    }
    return v;
}
